/// <summary>
/// class <c>METTelemetryPOStatusInfoEvent</c> is used to log error event whenever purchase order status info event.
/// </summary>
internal final class METTelemetryPOStatusInfoEvent extends ISMTelemetryBase
{
}

Method.Source:
/// <summary>
/// Initialize the class <c>METTelemetryPOStatusInfoEvent</c>
/// </summary>
/// <returns> Instance of class <c>METTelemetryPOStatusInfoEvent</c> </returns>
public static METTelemetryPOStatusInfoEvent construct()
{
    return new METTelemetryPOStatusInfoEvent();
}

/// <summary>
/// Run confirmation journal error event
/// </summary>
/// <param name = "_purchId"> purchase id </param>

public static void runTelemetryEvent(PurchTable _purchTable)
{
    METTelemetryPOStatusInfoEvent pOStatusEvent = METTelemetryPOStatusInfoEvent::construct();

    pOStatusEvent.addRunTimePropertyToAppinsights(_purchTable);

    pOStatusEvent.processEvent(METTelemetryEventNames::POStatusEvent);
}

protected void new()
{
    super();

    this.eventId = METTelemetryEventNames::POStatusEvent;
}

/// <summary>
/// if the log level is set to information it will log the request and response data as wekk as there is an error
/// </summary>
/// <returns> a boolean value </returns>
protected boolean shouldLogEvent()
{
    return true;
}

/// <summary>
/// Add runtime telemetry property to application insights.
/// </summary>
/// <param name = "_purchTable"> table <c>_purchTable</c> </param>
public void addRunTimePropertyToAppinsights(PurchTable _purchTable)
{
    this.addRuntimeProperty('PurchaseOrderId', _purchTable.PurchId);
    this.addRuntimeProperty('warehouseId' ,_purchTable.InventLocationId);
    this.addRuntimeProperty('VendorOrderReference', _purchTable.VendorRef);
    this.addRuntimeProperty('VendorAccount', _purchTable.OrderAccount);
    this.addRuntimeProperty('VendorAccount', _purchTable.InventLocationId);
    this.addRuntimeProperty('VendorOrderReference', _purchTable.VendorRef);
    this.addRuntimeProperty('BuyerGroup', _purchTable.ItemBuyerGroupId);
    this.addRuntimeProperty('Status', enum2str(_purchTable.PurchStatus));
}
